SELECT (SELECT COUNT(*) FROM usuarios) AS usuarios, (SELECT COUNT(*) FROM alunos) AS alunos, (SELECT COUNT(*) FROM responsaveis) AS responsaveis, (SELECT COUNT(*) FROM notas) AS notas, (SELECT COUNT(*) FROM acompanhamentos) AS acamp, (SELECT COUNT(*) FROM responsavel_usuario) AS vinculos, (SELECT COUNT(*) FROM seguranca_usuario WHERE usuario_id NOT IN (SELECT id FROM usuarios)) AS seg_orfaos, (SELECT COUNT(*) FROM sessoes WHERE usuario_id NOT IN (SELECT id FROM usuarios)) AS sess_orfaos, (SELECT COUNT(*) FROM redefinicao_senha WHERE usuario_id NOT IN (SELECT id FROM usuarios)) AS red_orfaos, (SELECT COUNT(*) FROM responsaveis WHERE id NOT IN (SELECT responsavel_id FROM alunos) AND id NOT IN (SELECT responsavel2_id FROM alunos)) AS resp_orfaos;